    [2690]={name="Latched Belt",sourceType="quest_reward",instructions="Reward from the quest “Grape Manifest” — pick it over the other choices. In Northshire Valley.",zone="Northshire Valley",questName="Grape Manifest",lore="Now that my crop is saved, take this Grape Manifest to Brother Neals. He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes."},
    [2691]={name="Outfitter Boots",sourceType="quest_reward",instructions="Reward from the quest “Skirmish at Echo Ridge” — pick it over the other choices. In Northshire Valley.",zone="Northshire Valley",questName="Skirmish at Echo Ridge",lore="Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."},
    [2694]={name="Settler's Leggings",sourceType="quest_reward",instructions="Reward from the quest “Stolen Silver” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Stolen Silver",lore="You may have killed the raptors, but the silver they stole must be recovered! I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds."},
