    [3511]={name="Cloak of the People's Militia",sourceType="quest_reward",instructions="Reward from the quest “Red Leather Bandanas” — pick it over the other choices. In Westfall.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
    [3570]={name="Bonegrinding Pestle",sourceType="quest_reward",instructions="Reward from the quest “Arugal's Folly” — pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Arugal's Folly",lore="As my understanding of Arugal's magic grows so does my disdain for the hapless fool. I am close to completing my research on his so called remedy."},
    [3582]={name="Acidproof Cloak",sourceType="quest_reward",instructions="Reward from the quest “A Recipe For Death” — pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="A Recipe For Death",lore="According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."},
