    [3758]={name="Crusader Belt",sourceType="quest_reward",instructions="Reward from the quest “Syndicate Assassins” — pick it over the other choices. In Alterac Mountains.",zone="Alterac Mountains",questName="Syndicate Assassins",lore="I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate."},
    [3765]={name="Brigand's Pauldrons",sourceType="quest_reward",instructions="Reward from the quest “Taretha's Gift” — pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Taretha's Gift",lore="The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace..."},
