    [4430]={name="Ethereal Talisman",sourceType="quest_reward",instructions="Reward from the quest “The Crown of Will”. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="The Crown of Will",lore="All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas."},
