    [4534]={name="Steel-clasped Bracers",sourceType="quest_reward",instructions="Reward from the quest “The Book of Ur” — pick it over the other choices. In Shadowfang Keep.",zone="Shadowfang Keep",questName="The Book of Ur",lore="Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection. Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to..."},
    [4549]={name="Seafire Band",sourceType="quest_reward",instructions="Reward from the quest “Death From Below” — pick it over the other choices. In Arathi Highlands.",zone="Arathi Highlands",questName="Death From Below",lore="This is bad. It seems the Daggerspines are amassing for an attack. Naga are known for their ruthlessness in battle. They will keep attacking until I am dead."},
