    [6721]={name="Chestplate of Kor",sourceType="quest_reward",instructions="Reward from the quest “Supplies to Auberdine” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Supplies to Auberdine",lore="Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own."},
    [6722]={name="Beastial Manacles",sourceType="quest_reward",instructions="Reward from the quest “Fallen Sky Lake” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Fallen Sky Lake",lore="Relara's fever has passed, but she is still very weak. I do not believe time alone will give her back the strength she has lost. I believe it will take the power of a moonstone."},
    [6723]={name="Medal of Courage",sourceType="quest_reward",instructions="Reward from the quest “Saving Yenniku” — pick it over the other choices. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Saving Yenniku",lore="I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."},
    [6725]={name="Marbled Buckler",sourceType="quest_reward",instructions="Reward from the quest “The Crone of the Kraul” — pick it over the other choices. In Razorfen Kraul.",zone="Razorfen Kraul",questName="The Crone of the Kraul",lore="Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was. We must not let their valiance go for naught. This crone... Charlga Razorflank..."},
    [6730]={name="Ironforge Chain",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
