    [9588]={name="Nogg's Gold Ring",sourceType="quest_reward",instructions="Reward from the quest “Nogg's Ring Redo”. In Orgrimmar.",zone="Orgrimmar",questName="Nogg's Ring Redo",lore="No, no, no - I'm not all of the sudden saying that the ring is mine."},
    [9599]={name="Barkmail Leggings",sourceType="quest_reward",instructions="Reward from the quest “The Relics of Wakening” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Relics of Wakening",lore="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."},
    [9603]={name="Gritroot Staff",sourceType="quest_reward",instructions="Reward from the quest “The Relics of Wakening” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Relics of Wakening",lore="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."},
    [9625]={name="Dual Reinforced Leggings",sourceType="quest_reward",instructions="Reward from the quest “Rig Wars” — pick it over the other choices. In Gnomeregan.",zone="Gnomeregan",questName="Rig Wars",lore="Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."},
    [9637]={name="Shinkicker Boots",sourceType="quest_reward",instructions="Reward from the quest “Deliver to MacKinley” — pick it over the other choices. In Tanaris.",zone="Tanaris",questName="Deliver to MacKinley",lore="Thanks again for your help. Here's a bottle of Steamwheedle bilge rum. Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."},
    [9640]={name="Vice Grips",sourceType="boss_drop",instructions="Drops from Antu'sul in Zul'Farrak.",zone="Zul'Farrak",npc="Antu'sul",lore="A plain plate glove that became famous for its random enchants -- the of Strength roll is a 7.9% chance and was worth chasing over guaranteed epics for years."},
