    [11809]={name="Flame Wrath",sourceType="boss_drop",instructions="Drops from Ambassador Flamelash in Blackrock Depths.",zone="Blackrock Depths",npc="Ambassador Flamelash",lore="Ragnaros's envoy to the Dark Iron in Blackrock Depths, sent to keep the dwarves loyal to the Firelord.",proc="Chance on hit: Envelops the caster with a Fire shield for 15 sec and shoots a ring of fire dealing 130 to 170 damage to all nearby enemies."},
    [11811]={name="Smoking Heart of the Mountain",sourceType="profession",instructions="Crafted with Enchanting (requires skill 1).",profession="Enchanting"},
    [11815]={name="Hand of Justice",sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan in Blackrock Depths.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Prints five Strength and eight Stamina and is worth vastly more than that: the extra attack it grants is the reason a Blackrock Depths trinket stayed in raid sets for years.",proc="Equip: Chance on melee hit to gain 1 extra attack. (2s cooldown)"},
    [11817]={name="Lord General's Sword",sourceType="boss_drop",instructions="Drops from General Angerforge in Blackrock Depths.",zone="Blackrock Depths",npc="General Angerforge",proc="Chance on hit: Increases attack power by 50 for 30 sec."},
    [11849]={name="Rustmetal Bracers",sourceType="quest_reward",instructions="Reward from the quest “Scavenging Deathknell” — pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
    [11852]={name="Roamer's Leggings",sourceType="quest_reward",instructions="Reward from the quest “Rattling the Rattlecages” — pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Rattling the Rattlecages",lore="You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."},
    [11858]={name="Battlehard Cape",sourceType="quest_reward",instructions="Reward from the quest “A Grim Discovery” — pick it over the other choices. In Feralas.",zone="Feralas",questName="A Grim Discovery",lore="What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."},
    [11862]={name="White Bone Band",sourceType="quest_reward",instructions="Reward from the quest “Bone-Bladed Weapons” — pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Bone-Bladed Weapons",lore="In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."},
    [11872]={name="Eschewal Greaves",sourceType="quest_reward",instructions="Reward from the quest “Calm Before the Storm” — pick it over the other choices. In Darnassus.",zone="Darnassus",questName="Calm Before the Storm",lore="your help has been immeasurable. The time will come, no doubt, when I'll ask for your assistance against the silithid once more."},
    [11905]={name="Linken's Boomerang",sourceType="quest_reward",instructions="Reward from the quest “It's Dangerous to Go Alone”. In Un'Goro Crater.",zone="Un'Goro Crater",questName="It's Dangerous to Go Alone",lore="I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero...",proc="Use: Flings a magical boomerang towards target enemy dealing 113 to 187 damage and has a chance to stun or disarm them. (3 Min Cooldown)"},
    [11910]={name="Bejeweled Legguards",sourceType="quest_reward",instructions="Reward from the quest “A Little Help From My Friends” — pick it over the other choices. In Un'Goro Crater.",zone="Un'Goro Crater",questName="A Little Help From My Friends",lore="Ugh... It's so hot... I was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion."},
