    [15588]={name="Bracesteel Belt",sourceType="quest_reward",instructions="Reward from the quest “Clam Bait” — pick it over the other choices. In Desolace.",zone="Desolace",questName="Clam Bait",lore="You have the look of a fisherman! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?"},
