    [15795]={name="Emerald Mist Gauntlets",sourceType="quest_reward",instructions="Reward from the quest “The Crystal of Zin-Malor” — pick it over the other choices. In Winterspring.",zone="Winterspring",questName="The Crystal of Zin-Malor",lore="Quite impressive. The crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded."},
