    [16886]={name="Outlaw Sabre",sourceType="quest_reward",instructions="Reward from the quest “Baron Aquanis” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Baron Aquanis",lore="The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."},
    [16959]={name="Bracelets of Wrath",sourceType="boss_drop",instructions="Drops from Razorgore the Untamed in Blackwing Lair.",zone="Blackwing Lair",npc="Razorgore the Untamed",lore="Set to guard the stolen dragon eggs. The raid takes control of the orb he is chained to and turns him on the clutch he was protecting."},
    [16978]={name="Warsong Gauntlets",sourceType="quest_reward",instructions="Reward from the quest “Warsong Supplies” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Warsong Supplies",lore="We are in short supply of a few items at the Warsong lumber camp!"},
    [16986]={name="Sandspire Gloves",sourceType="quest_reward",instructions="Reward from the quest “New Life” — pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="New Life",lore="As you have seen, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale."},
    [16996]={name="Gorewood Bow",sourceType="quest_reward",instructions="Reward from the quest “The Scarlet Oracle, Demetria” — pick it over the other choices. In Eastern Plaguelands.",zone="Eastern Plaguelands",questName="The Scarlet Oracle, Demetria",lore="Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge."},
    [17006]={name="Cobalt Legguards",sourceType="quest_reward",instructions="Reward from the quest “King of the Foulweald” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="King of the Foulweald",lore="another tribe of Furbolgs, the Foulweald, live southeast of Astranaar. They are not as many as the Thistlefur, but their ferocity poses a future threat."},
    [17013]={name="Dark Iron Leggings",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [17014]={name="Dark Iron Bracers",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [17076]={name="Bonereaver's Edge",sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="Bonereaver's Edge strips the armour off whatever it hits. Ragnaros's court had little use for subtlety.",proc="Chance on hit: Your attacks ignore 700 of your enemies' armor for 10 sec. This effect stacks up to 3 times."},
    [17185]={name="Round Buckler",sourceType="vendor",instructions="Bought from Sana in Orgrimmar.",zone="Orgrimmar",npc="Sana"},
    [17186]={name="Small Targe",sourceType="vendor",instructions="Bought from Treall in The Exodar.",zone="The Exodar",npc="Treall"},
    [17694]={name="Band of the Fist",sourceType="quest_reward",instructions="Reward from the quest “Allegiance to the Old Gods” — pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Allegiance to the Old Gods",lore="This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."},
    [17711]={name="Elemental Rockridge Leggings",sourceType="boss_drop",instructions="Drops from Princess Theradras in Maraudon.",zone="Maraudon",npc="Princess Theradras",lore="A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."},
    [17713]={name="Blackstone Ring",sourceType="boss_drop",instructions="Drops from Princess Theradras in Maraudon.",zone="Maraudon",npc="Princess Theradras",lore="A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."},
