    [19019]={name="Thunderfury, Blessed Blade of the Windseeker",sourceType="quest_reward",instructions="Reward from the quest “Rise, Thunderfury!”.",questName="Rise, Thunderfury!",lore="Forged for a Windseeker of the elemental lords and lost for an age. Waking it again takes the bindings of the left and right hand, the blessing of Thunderaan's own essence, and a smith willing to defy Ragnaros.",proc="Chance on hit: Blasts your enemy with lightning, dealing 300 Nature damage and then jumping to additional nearby enemies.  Each jump reduces that victim's Nature resistance by 25. "},
    [19024]={name="Arena Grand Master",sourceType="quest_reward",instructions="Reward from the quest “Arena Grandmaster”. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Arena Grandmaster",lore="Avast Lubber! Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!",proc="Use: Absorbs 750 to 1250 damage.  Lasts 20 sec. (15 Min Cooldown)"},
    [19037]={name="Emerald Peak Spaulders",sourceType="quest_reward",instructions="Reward from the quest “Zukk'ash Report” — pick it over the other choices. In Feralas.",zone="Feralas",questName="Zukk'ash Report",lore="You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache. The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde."},
    [19051]={name="Girdle of the Dawn",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
