    [19114]={name="Highland Bow",sourceType="quest_reward",instructions="Reward from the quest “Return to Primal Torntusk” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Return to Primal Torntusk",lore="Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."},
    [19117]={name="Laquered Wooden Plate Legplates",sourceType="quest_reward",instructions="Reward from the quest “Separation Anxiety” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Separation Anxiety",lore="Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."},
    [19120]={name="Rune of the Guard Captain",sourceType="quest_reward",instructions="Reward from the quest “Job Opening: Guard Captain of Revantusk Village”. In The Hinterlands.",zone="The Hinterlands",questName="Job Opening: Guard Captain of Revantusk Village",lore="With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open."},
    [19124]={name="Slagplate Leggings",sourceType="quest_reward",instructions="Reward from the quest “STOLEN: Smithing Tuyere and Lookout's Spyglass” — pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="STOLEN: Smithing Tuyere and Lookout's Spyglass",lore="The following items have been stolen: *One Dark Iron Tuyere. *One Lookout's Spyglass. A reward is being offered to individuals who find and return these pilfered items."},
    [19137]={name="Onslaught Girdle",sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [19159]={name="Woven Ivy Necklace",sourceType="quest_reward",instructions="Reward from the quest “Wanted: Vile Priestess Hexx and Her Minions” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
    [19350]={name="Heartstriker",sourceType="boss_drop",instructions="Drops from Broodlord Lashlayer in Blackwing Lair.",zone="Blackwing Lair",npc="Broodlord Lashlayer",lore="Nefarian's lieutenant, posted to hold the only way deeper into the lair."},
    [19376]={name="Archimtiros' Ring of Reckoning",sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [19384]={name="Master Dragonslayer's Ring",sourceType="quest_reward",instructions="Reward from the quest “The Lord of Blackrock” — pick it over the other choices. In Stormwind City.",zone="Stormwind City",questName="The Lord of Blackrock"},
    [19386]={name="Elementium Threaded Cloak",sourceType="boss_drop",instructions="Drops from Chromaggus in Blackwing Lair.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
    [19387]={name="Chromatic Boots",sourceType="boss_drop",instructions="Drops from Chromaggus in Blackwing Lair.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
    [19406]={name="Drake Fang Talisman",sourceType="boss_drop",instructions="Drops from Ebonroc in Blackwing Lair.",zone="Blackwing Lair",npc="Ebonroc",lore="Cut from the fang of one of Nefarian's drakes. Tanks wore it for the stun it shrugs off, not the numbers on it."},
    [19432]={name="Circle of Applied Force",sourceType="boss_drop",instructions="Drops from Flamegor in Blackwing Lair.",zone="Blackwing Lair",npc="Flamegor",lore="The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."},
