    [20640]={name="Southsea Head Bucket",sourceType="quest_reward",instructions="Reward from the quest “Southsea Shakedown” — pick it over the other choices. In Tanaris.",zone="Tanaris",questName="Southsea Shakedown",lore="They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson."},
    [20646]={name="Sandstrider's Mark",sourceType="quest_reward",instructions="Reward from the quest “Wanted - Deathclasp, Terror of the Sands” — pick it over the other choices. In Silithus.",zone="Silithus",questName="Wanted - Deathclasp, Terror of the Sands",lore="The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity."},
