    [21134]={name="Dark Edge of Insanity",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped.",proc="Chance on hit: Disorients the target, causing it to wander aimlessly for up to 3 sec."},
    [21316]={name="Leggings of the Ursa",sourceType="quest_reward",instructions="Reward from the quest “Deadwood of the North” — pick it over the other choices. In Timbermaw Hold.",zone="Timbermaw Hold",questName="Deadwood of the North",lore="There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."},
    [21329]={name="Conqueror's Crown",sourceType="quest_reward",instructions="Reward from the quest “Conqueror's Crown”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Crown",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21330]={name="Conqueror's Spaulders",sourceType="quest_reward",instructions="Reward from the quest “Conqueror's Spaulders”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Spaulders",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21331]={name="Conqueror's Breastplate",sourceType="quest_reward",instructions="Reward from the quest “Conqueror's Breastplate”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Breastplate",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21332]={name="Conqueror's Legguards",sourceType="quest_reward",instructions="Reward from the quest “Conqueror's Legguards”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Legguards",lore="You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."},
    [21333]={name="Conqueror's Greaves",sourceType="quest_reward",instructions="Reward from the quest “Conqueror's Greaves”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Conqueror's Greaves",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21459]={name="Crossbow of Imminent Doom",sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
    [21567]={name="Rune of Duty",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21568]={name="Rune of Duty",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21581]={name="Gauntlets of Annihilation",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21596]={name="Ring of the Godslayer",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21598]={name="Royal Qiraji Belt",sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21602]={name="Qiraji Execution Bracers",sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21618]={name="Hive Defiler Wristguards",sourceType="boss_drop",instructions="Drops from Princess Huhuran in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Princess Huhuran",lore="A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."},
    [21664]={name="Barbed Choker",sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."},
    [21665]={name="Mantle of Wicked Revenge",sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."},
    [21672]={name="Gloves of Enforcement",sourceType="boss_drop",instructions="Drops from Battleguard Sartura in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Battleguard Sartura",lore="The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."},
    [21674]={name="Gauntlets of Steadfast Determination",sourceType="boss_drop",instructions="Drops from Battleguard Sartura in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Battleguard Sartura",lore="The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."},
    [21677]={name="Ring of the Qiraji Fury",sourceType="boss_drop",instructions="Drops from Viscidus in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Viscidus",lore="A living mass of qiraji poison. It has to be frozen solid and then shattered, which is not how most things die."},
    [21688]={name="Boots of the Fallen Hero",sourceType="boss_drop",instructions="Drops from Vem in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Vem",lore="The third of the qiraji council, who charges the moment the fight begins and does not stop."},
    [21692]={name="Triad Girdle",sourceType="boss_drop",instructions="Drops from Lord Kri in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Lord Kri",lore="One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."},
    [21701]={name="Cloak of Concentrated Hatred",sourceType="boss_drop",instructions="Drops from The Prophet Skeram in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="The Prophet Skeram",lore="C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."},
    [21710]={name="Cloak of the Fallen God",sourceType="quest_reward",instructions="Reward from the quest “The Savior of Kalimdor” — pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [21814]={name="Breastplate of Annihilation",sourceType="boss_drop",instructions="Drops from The Prophet Skeram in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="The Prophet Skeram",lore="C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."},
    [21995]={name="Boots of Heroism",sourceType="quest_reward",instructions="Reward from the quest “Anthion's Parting Words”. In Ironforge.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [21997]={name="Breastplate of Heroism",sourceType="quest_reward",instructions="Reward from the quest “Saving the Best for Last”. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [21998]={name="Gauntlets of Heroism",sourceType="quest_reward",instructions="Reward from the quest “Just Compensation”. In Ironforge.",zone="Ironforge",questName="Just Compensation",lore="I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gauntlets that you wish to upgrade."},
    [21999]={name="Helm of Heroism",sourceType="quest_reward",instructions="Reward from the quest “Saving the Best for Last”. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22150]={name="Beads of Ogre Might",sourceType="quest_reward",instructions="Reward from the quest “Falrin's Vendetta” — pick it over the other choices. In Dire Maul.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
    [22205]={name="Black Steel Bindings",sourceType="world_drop",instructions="Drops from Watchman Doomgrip (rare elite).",npc="Watchman Doomgrip"},
