    [22416]={name="Dreadnaught Breastplate",sourceType="quest_reward",instructions="Reward from the quest “Dreadnaught Breastplate”. In Naxxramas.",zone="Naxxramas",questName="Dreadnaught Breastplate",lore="During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes."},
