    [22423]={name="Dreadnaught Bracers",sourceType="quest_reward",instructions="Reward from the quest “Dreadnaught Bracers”. In Naxxramas.",zone="Naxxramas",questName="Dreadnaught Bracers",lore="During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes."},
    [22659]={name="Medallion of the Dawn",sourceType="quest_reward",instructions="Reward from the quest “Epic Armaments of Battle - Friend of the Dawn” — pick it over the other choices. In Eastern Plaguelands.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"},
    [22732]={name="Mark of C'Thun",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [22798]={name="Might of Menethil",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Menethil was the royal line of Lordaeron -- King Terenas, and his son Arthas, who became the Lich King. A warhammer carrying that name, guarded by the lich who served Arthas, is not an accident."},
    [22802]={name="Kingsfall",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22808]={name="The Castigator",sourceType="boss_drop",instructions="Drops from Thaddius in Naxxramas.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter."},
    [22810]={name="Toxin Injector",sourceType="boss_drop",instructions="Drops from Grobbulus in Naxxramas.",zone="Naxxramas",npc="Grobbulus",lore="A walking vat. The Scourge used him to field-test new strains of the plague on whatever wandered into Naxxramas."},
    [22811]={name="Soulstring",sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease"},
    [22812]={name="Nerubian Slavemaker",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22816]={name="Hatchet of Sundered Bone",sourceType="boss_drop",instructions="Drops from Noth the Plaguebringer in Naxxramas.",zone="Naxxramas",npc="Noth the Plaguebringer",lore="A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."},
    [22818]={name="The Plague Bearer",sourceType="boss_drop",instructions="Drops from Patchwerk in Naxxramas.",zone="Naxxramas",npc="Patchwerk",lore="An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."},
    [22936]={name="Wristguards of Vengeance",sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22938]={name="Cryptfiend Silk Cloak",sourceType="boss_drop",instructions="Drops from Anub'Rekhan in Naxxramas.",zone="Naxxramas",npc="Anub'Rekhan",lore="A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."},
    [22954]={name="Kiss of the Spider",sourceType="boss_drop",instructions="Drops from Maexxna in Naxxramas.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Use: Increases your haste rating by 200 for 15 sec. (2 Min Cooldown)"},
    [23000]={name="Plated Abomination Ribcage",sourceType="boss_drop",instructions="Drops from Thaddius in Naxxramas.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter."},
    [23014]={name="Iblis, Blade of the Fallen Seraph",sourceType="boss_drop",instructions="Drops from Instructor Razuvious in Naxxramas.",zone="Naxxramas",npc="Instructor Razuvious",lore="A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson."},
    [23023]={name="Sadist's Collar",sourceType="boss_drop",instructions="Drops from Gothik the Harvester in Naxxramas.",zone="Naxxramas",npc="Gothik the Harvester",lore="Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."},
    [23038]={name="Band of Unnatural Forces",sourceType="boss_drop",instructions="Drops from Loatheb in Naxxramas.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
    [23041]={name="Slayer's Crest",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases attack power by 260 for 20 sec. (2 Min Cooldown)"},
    [23043]={name="The Face of Death",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
    [23045]={name="Shroud of Dominion",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
    [23053]={name="Stormrage's Talisman of Seething",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23054]={name="Gressil, Dawn of Ruin",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23068]={name="Legplates of Carnage",sourceType="boss_drop",instructions="Drops from Heigan the Unclean in Naxxramas.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23071]={name="Leggings of Apocalypse",sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease"},
    [23127]={name="Cloak of Revanchion",sourceType="world_drop",instructions="Drops from Revanchion (rare elite).",npc="Revanchion"},
    [23132]={name="Lord Blackwood's Blade",sourceType="world_drop",instructions="Drops from Lord Blackwood (rare elite).",npc="Lord Blackwood"},
    [23139]={name="Lord Blackwood's Buckler",sourceType="world_drop",instructions="Drops from Lord Blackwood (rare elite).",npc="Lord Blackwood"},
    [23170]={name="The Frozen Clutch",sourceType="world_drop",instructions="Drops from Scorn (rare elite).",npc="Scorn"},
    [23206]={name="Mark of the Champion",sourceType="quest_reward",instructions="Reward from the quest “The Fall of Kel'Thuzad” — pick it over the other choices. In Naxxramas.",zone="Naxxramas",questName="The Fall of Kel'Thuzad",lore="Struck for the war against the Scourge and the Old Gods. It does nothing at all against anything else, which is the point of the mark."},
    [23219]={name="Girdle of the Mentor",sourceType="boss_drop",instructions="Drops from Instructor Razuvious in Naxxramas.",zone="Naxxramas",npc="Instructor Razuvious",lore="A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson."},
    [23226]={name="Ghoul Skin Tunic",sourceType="world_drop",instructions="World drop — drops from 29 creature types around level 60-63. Also found on the auction house."},
    [23323]={name="Crown of the Fire Festival",sourceType="quest_reward",instructions="Reward from the quest “A Thief's Reward”.",questName="A Thief's Reward",seasonal=true,lore="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more..."},
    [23324]={name="Mantle of the Fire Festival",sourceType="quest_reward",instructions="Reward from the quest “Wild Fires in the Eastern Kingdoms”.",questName="Wild Fires in the Eastern Kingdoms",seasonal=true,lore="Our celebration of the flame is spread throughout the land. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue."},
    [23557]={name="Larvae of the Great Worm",sourceType="boss_drop",instructions="Drops from Ouro.",npc="Ouro",lore="A sandworm grown enormous under the desert, surfacing only to feed."},
    [23577]={name="The Hungering Cold",sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
